82	// Navigation-only role switcher. Roles are additive in this system — clicking
83	// "Savininkas" just routes to /owner; it does not change the user's primary
84	// role. Only options the user actually has access to are shown.
85	function RoleSwitcher() {
86	  const [, navigate] = useLocation();
87	  const { isCoach, isOwner } = useRole();
88	  const [open, setOpen] = useState(false);
89	
90	  const options: Array<{ label: string; href: string }> = [];
91	  options.push({ label: "Žaidėjas", href: "/" });
92	  if (isOwner) options.push({ label: "Savininkas", href: "/owner" });
93	  if (isCoach) options.push({ label: "Treneris", href: "/coach/dashboard" });
94	
95	  if (options.length < 2) return null;
96	
97	  return (
98	    <div className="relative">
99	      <button
100	        type="button"
101	        onClick={() => setOpen((o) => !o)}
102	        className="w-full flex items-center justify-between px-3 py-2 rounded-lg text-sm font-medium bg-muted/40 hover:bg-muted transition-colors"
103	      >
104	        <span className="flex items-center gap-2">
105	          <span className="text-[10px] text-muted-foreground uppercase tracking-widest font-semibold">
106	            Rodinys
107	          </span>
108	          <span>Treneris</span>
109	        </span>
110	        <ChevronDown className={`h-3.5 w-3.5 transition-transform ${open ? "rotate-180" : ""}`} />
111	      </button>
112	      {open && (
113	        <div className="absolute left-0 right-0 mt-1 z-10 rounded-lg border bg-card shadow-md overflow-hidden">
114	          {options.map((opt) => (
115	            <button
116	              key={opt.label}
117	              type="button"
118	              onClick={() => {
119	                setOpen(false);
120	                navigate(opt.href);
121	              }}
122	              className="w-full text-left px-3 py-2 text-sm hover:bg-muted transition-colors"
123	            >
124	              {opt.label}
125	            </button>
126	          ))}
127	        </div>
128	      )}
129	    </div>
130	  );
131	}
132	
133	function NavLink({
134	  item,
135	  active,
136	  onNavigate,
137	}: {
138	  item: NavItem;
139	  active: boolean;
140	  onNavigate: (href: string) => void;
141	}) {
142	  return (
143	    <a
144	      href={`${BASE_URL}${item.href}`}
145	      onClick={(e) => {
146	        if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || e.button !== 0) return;
147	        e.preventDefault();
