37	  sports?: string[];
38	  travelPolicy?: TravelPolicy;
39	  courtPaymentModel?: CourtPaymentModel;
40	  cancellationPolicy?: CoachCancellationPolicy;
41	  promotedUntil?: string | null;
42	}
43	
44	interface FormState {
45	  bio: string;
46	  experienceYears: string;
47	  qualifications: string[];
48	  isAcceptingStudents: boolean;
49	  travelPolicy: TravelPolicy;
50	  courtPaymentModel: CourtPaymentModel;
51	  cancellationPolicy: CoachCancellationPolicy;
52	}
53	
54	const EMPTY_FORM: FormState = {
55	  bio: "",
56	  experienceYears: "",
57	  qualifications: [],
58	  isAcceptingStudents: true,
59	  travelPolicy: "affiliated_only",
60	  courtPaymentModel: "student_pays_court",
61	  cancellationPolicy: "standard",
62	};
63	
64	const MAX_QUALIFICATIONS = 20;
65	const MAX_QUALIFICATION_LENGTH = 200;
66	
67	export default function CoachSettings() {
68	  const { toast } = useToast();
69	  const qc = useQueryClient();
70	
71	  const { asCoachId } = useViewAsCoach();
72	  const isViewingAs = asCoachId != null;
73	  const { data: profile, isLoading } = useQuery<MyCoachProfile>({
74	    queryKey: ["coach-me-profile", asCoachId],
75	    queryFn: () => customFetch<MyCoachProfile>(withCoachViewAs(`${API}/coaches/me`)),
76	    staleTime: 60_000,
77	  });
78	
79	  // Live Stripe Connect status. The endpoint performs a live retrieve against
80	  // Stripe and reconciles user_profiles.stripeAccountStatus, so just loading
81	  // this page is enough to pull the coach out of the marketplace shadow as
82	  // soon as Stripe flips them back to "active".
83	  type StripeStatusValue = "not_connected" | "pending" | "active";
84	  const { data: stripeStatus } = useQuery<{
85	    status: StripeStatusValue;
86	    accountId: string | null;
87	    disabledReason?: string | null;
88	  }>({
89	    queryKey: ["stripe-connect-status"],
90	    queryFn: () => customFetch(`${API}/stripe/connect/status`),
91	  });
92	  const isHiddenFromMarketplace =
93	    stripeStatus != null && stripeStatus.status !== "active";
94	
95	  // Re-check Stripe state whenever the tab regains focus (e.g. after the
96	  // coach completes onboarding in a Stripe popup). Same pattern owner-facilities
97	  // uses so the banner clears without a manual reload.
98	  useEffect(() => {
99	    const onFocus = () => {
100	      qc.invalidateQueries({ queryKey: ["stripe-connect-status"] });
101	    };
102	    window.addEventListener("focus", onFocus);
103	    return () => window.removeEventListener("focus", onFocus);
104	  }, [qc]);
105	
106	  const [stripeOpening, setStripeOpening] = useState(false);
107	  const openStripeConnect = async () => {
108	    setStripeOpening(true);
109	    try {
110	      const r = await customFetch<{ url: string }>(`${API}/stripe/connect`, {
111	        method: "POST",
112	      });
113	      window.open(r.url, "_blank", "noopener,noreferrer");
114	    } catch (err) {
115	      toast({
116	        title: "Klaida atidarant Stripe",
117	        description: (err as Error).message,
118	        variant: "destructive",
119	      });
120	    } finally {
121	      setStripeOpening(false);
122	    }
123	  };
124	
125	  const [form, setForm] = useState<FormState>(EMPTY_FORM);
126	
127	  // Seed the form from the server response once it arrives. We render an
128	  // empty form before profile loads — Inputs need string values, not null.
129	  useEffect(() => {
130	    if (!profile) return;
131	    setForm({
132	      bio: profile.bio ?? "",
133	      experienceYears:
134	        profile.experienceYears != null ? String(profile.experienceYears) : "",
135	      qualifications: profile.qualifications ?? [],
136	      isAcceptingStudents: profile.isAcceptingStudents ?? true,
137	      travelPolicy: profile.travelPolicy ?? "affiliated_only",
138	      courtPaymentModel: profile.courtPaymentModel ?? "student_pays_court",
139	      cancellationPolicy: profile.cancellationPolicy ?? "standard",
140	    });
141	  }, [profile]);
142	
143	  const save = useMutation({
144	    mutationFn: async () => {
145	      // The /coaches/me PUT endpoint expects the full upsert body — name and
146	      // email are required by the zod schema, so we include them unchanged
147	      // from the server-known profile.
148	      if (!profile) throw new Error("Profilis dar nepasiruošė");
149	      return customFetch<MyCoachProfile>(`${API}/coaches/me`, {
150	        method: "PUT",
151	        headers: { "Content-Type": "application/json" },
152	        body: JSON.stringify({
153	          name: profile.name,
154	          email: profile.email,
155	          bio: form.bio || null,
156	          // pricePerHour intentionally not sent — server derives it from
157	          // active coach_services. See lib/coach-pricing.ts.
158	          experienceYears:
159	            form.experienceYears && Number.isFinite(Number(form.experienceYears))
160	              ? Math.max(0, Math.round(Number(form.experienceYears)))
161	              : null,
162	          qualifications: form.qualifications
163	            .map((q) => q.trim())
164	            .filter((q) => q.length > 0)
165	            .slice(0, MAX_QUALIFICATIONS),
166	          isAcceptingStudents: form.isAcceptingStudents,
167	          travelPolicy: form.travelPolicy,
168	          courtPaymentModel: form.courtPaymentModel,
169	          cancellationPolicy: form.cancellationPolicy,
170	        }),
171	      });
172	    },
173	    onSuccess: () => {
174	      toast({ title: "Profilis išsaugotas" });
175	      qc.invalidateQueries({ queryKey: ["coach-me-profile"] });
176	      qc.invalidateQueries({ queryKey: ["coach"] });
177	      qc.invalidateQueries({ queryKey: ["coaches"] });
178	    },
179	    onError: (e: Error) => {
180	      toast({ title: "Klaida", description: e.message, variant: "destructive" });
181	    },
182	  });
183	
184	  function onSubmit(e: FormEvent<HTMLFormElement>) {
185	    e.preventDefault();
186	    if (save.isPending) return;
187	    save.mutate();
188	  }
189	
190	  return (
191	    <CoachLayout title="Nustatymai">
192	      <div className="px-4 md:px-6 py-6 max-w-2xl space-y-8">
193	        <header className="flex flex-col gap-1">
194	          <h1 className="text-2xl font-semibold tracking-tight">Nustatymai</h1>
195	          <p className="text-sm text-muted-foreground">
196	            Atnaujinkite savo trenerio profilio detales, valandinę kainą ir prieinamumą.
197	          </p>
198	        </header>
199	
200	        {isHiddenFromMarketplace && (
201	          <div
202	            role="alert"
203	            className="rounded-2xl border-2 border-destructive/40 bg-destructive/10 p-4 flex items-start gap-3"
204	          >
205	            <AlertTriangle className="w-5 h-5 text-destructive shrink-0 mt-0.5" />
206	            <div className="flex-1 min-w-0 space-y-2">
207	              <p className="text-sm font-semibold text-destructive">
208	                ⚠️ Jūsų profilis yra paslėptas nuo žaidėjų
209	              </p>
210	              <p className="text-sm text-destructive/90">
211	                Prijunkite arba atnaujinkite banko sąskaitos informaciją, kad galėtumėte priimti užsakymus.
212	                Paslaugų katalogą galite ruošti ir dabar — jis taps matomas iškart, kai Stripe sąskaita bus aktyvuota.
213	              </p>
214	              {stripeStatus?.disabledReason && (
215	                <p className="text-xs text-destructive/80">
216	                  Stripe priežastis: <code className="font-mono">{stripeStatus.disabledReason}</code>
217	                </p>
218	              )}
219	              <Button
220	                size="sm"
221	                variant="destructive"
222	                onClick={openStripeConnect}
223	                disabled={stripeOpening}
224	              >
225	                {stripeStatus?.status === "pending"
226	                  ? "Užbaigti Stripe sąskaitos patvirtinimą"
227	                  : "Prijungti banko sąskaitą"}
228	                <ExternalLink className="w-3.5 h-3.5 ml-1.5" />
229	              </Button>
230	            </div>
231	          </div>
232	        )}
233	
234	        {isLoading ? (
235	          <div className="space-y-4">
236	            <Skeleton className="h-10" />
237	            <Skeleton className="h-24" />
238	            <Skeleton className="h-10" />
239	            <Skeleton className="h-10" />
240	          </div>
241	        ) : !profile ? (
242	          <div className="rounded-2xl border bg-card px-6 py-10 text-center text-sm text-muted-foreground">
243	            Trenerio profilio dar nėra.
244	          </div>
245	        ) : (
246	          <>
247	            <div className="rounded-2xl border bg-card px-5 py-4 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
248	              <div>
249	                <h2 className="text-sm font-semibold">Iškelti paieškoje</h2>
250	                <p className="text-xs text-muted-foreground mt-0.5">
251	                  Jūsų profilis 7 dienas bus rodomas pirmiausia trenerių sąraše.
252	                </p>
253	              </div>
254	              <PromoteButton
255	                targetType="coach"
256	                targetId={profile.id}
257	                promotedUntil={profile.promotedUntil}
258	                size="sm"
259	              />
260	            </div>
261	
262	            <form onSubmit={onSubmit} className="space-y-5">
263	              <div className="space-y-1.5">
264	                <Label htmlFor="bio">Apie mane</Label>
265	                <Textarea
266	                  id="bio"
267	                  rows={4}
268	                  value={form.bio}
269	                  onChange={(e) => setForm((f) => ({ ...f, bio: e.target.value }))}
270	                  placeholder="Trumpa biografija, treniravimo stilius, pasiekimai..."
271	                />
272	              </div>
273	
274	              <div className="rounded-lg border bg-muted/30 px-3 py-2.5 flex items-start gap-3">
275	                <div className="flex-1 min-w-0">
276	                  <div className="text-[10px] uppercase tracking-widest text-muted-foreground font-semibold">
277	                    Bazinė valandinė kaina paieškoje
278	                  </div>
279	                  <div className="text-base font-semibold">
280	                    {profile?.pricePerHour != null && profile.pricePerHour > 0
281	                      ? `${centsToEuroString(profile.pricePerHour)} €/val.`
282	                      : "—"}
283	                  </div>
284	                  <p className="text-[11px] text-muted-foreground mt-0.5">
285	                    Apskaičiuojama automatiškai pagal pigiausią aktyvią jūsų paslaugą.
286	                    Kainas keiskite profilio puslapyje skiltyje „Mano paslaugos".
287	                  </p>
288	                </div>
289	              </div>
290	
291	              <div className="space-y-1.5">
292	                <Label htmlFor="experience">Patirtis (metais)</Label>
293	                <Input
294	                  id="experience"
295	                  type="number"
296	                  min={0}
297	                  step={1}
298	                  value={form.experienceYears}
299	                  onChange={(e) =>
300	                    setForm((f) => ({ ...f, experienceYears: e.target.value }))
301	                  }
302	                  placeholder="5"
303	                />
304	              </div>
305	
306	              <div className="space-y-2">
307	                <Label>Kvalifikacijos</Label>
308	                <p className="text-[11px] text-muted-foreground -mt-1">
309	                  Sertifikatai, licencijos, diplomai. Vienas įrašas — viena eilutė.
310	                </p>
311	                <div className="space-y-2">
312	                  {form.qualifications.map((q, idx) => (
313	                    <div key={idx} className="flex gap-2">
314	                      <Input
315	                        value={q}
316	                        maxLength={MAX_QUALIFICATION_LENGTH}
317	                        onChange={(e) =>
318	                          setForm((f) => {
319	                            const next = [...f.qualifications];
320	                            next[idx] = e.target.value;
321	                            return { ...f, qualifications: next };
322	                          })
323	                        }
324	                        placeholder="pvz. Lietuvos padelio federacijos treneris"
325	                      />
326	                      <Button
327	                        type="button"
328	                        size="icon"
329	                        variant="ghost"
330	                        onClick={() =>
331	                          setForm((f) => ({
332	                            ...f,
333	                            qualifications: f.qualifications.filter((_, i) => i !== idx),
334	                          }))
335	                        }
336	                        aria-label="Pašalinti kvalifikaciją"
337	                      >
338	                        <X className="w-4 h-4" />
339	                      </Button>
340	                    </div>
341	                  ))}
342	                </div>
343	                <Button
344	                  type="button"
345	                  variant="outline"
346	                  size="sm"
347	                  disabled={form.qualifications.length >= MAX_QUALIFICATIONS}
348	                  onClick={() =>
349	                    setForm((f) => ({
350	                      ...f,
351	                      qualifications: [...f.qualifications, ""],
352	                    }))
353	                  }
354	                >
355	                  <Plus className="w-4 h-4 mr-1.5" />
356	                  Pridėti kvalifikaciją
357	                </Button>
358	              </div>
359	
360	              <div className="flex items-center justify-between rounded-2xl border bg-card px-4 py-3">
361	                <div>
362	                  <Label htmlFor="accepting" className="text-sm font-medium">
363	                    Priimu naujus mokinius
364	                  </Label>
365	                  <p className="text-xs text-muted-foreground mt-0.5">
366	                    Kai išjungta, jūsų profilis lieka matomas, bet nepriimsite naujų užklausų.
367	                  </p>
368	                </div>
369	                <Switch
370	                  id="accepting"
371	                  checked={form.isAcceptingStudents}
372	                  onCheckedChange={(checked) =>
373	                    setForm((f) => ({ ...f, isAcceptingStudents: checked }))
374	                  }
375	                />
376	              </div>
377	
378	              <fieldset className="space-y-2 rounded-2xl border bg-card p-4">
379	                <legend className="text-sm font-medium px-1">Kelionių politika</legend>
380	                <p className="text-xs text-muted-foreground -mt-0.5">
381	                  Pasirinkite, kur galite vesti treniruotes.
382	                </p>
383	                <RadioGroup
384	                  value={form.travelPolicy}
385	                  onValueChange={(v) =>
386	                    setForm((f) => ({ ...f, travelPolicy: v as TravelPolicy }))
387	                  }
388	                  className="space-y-2 pt-1"
389	                >
390	                  <label className="flex items-start gap-3 rounded-lg border p-3 cursor-pointer hover:bg-muted/40 transition-colors">
391	                    <RadioGroupItem value="affiliated_only" id="travel-affiliated" className="mt-0.5" />
392	                    <div className="flex-1 min-w-0">
393	                      <div className="text-sm font-medium">Tik pasirinktose aikštelėse</div>
394	                      <div className="text-xs text-muted-foreground">
395	                        Treniruotės vyksta tik su jumis partneriaujančiose aikštelėse.
396	                      </div>
397	                    </div>
398	                  </label>
399	                  <label className="flex items-start gap-3 rounded-lg border p-3 cursor-pointer hover:bg-muted/40 transition-colors">
400	                    <RadioGroupItem value="any_court" id="travel-any" className="mt-0.5" />
401	                    <div className="flex-1 min-w-0">
402	                      <div className="text-sm font-medium">Galiu atvykti į bet kurią aikštelę</div>
403	                      <div className="text-xs text-muted-foreground">
404	                        Mokiniai gali užsisakyti treniruotę bet kokioje aikštelėje, ne tik partnerinėse.
405	                      </div>
406	                    </div>
407	                  </label>
408	                </RadioGroup>
409	              </fieldset>
410	
411	              <fieldset className="space-y-2 rounded-2xl border bg-card p-4">
412	                <legend className="text-sm font-medium px-1">Aikštelės apmokėjimas</legend>
413	                <p className="text-xs text-muted-foreground -mt-0.5">
414	                  Kas apmoka aikštelės nuomą už pamoką?
415	                </p>
416	                <RadioGroup
417	                  value={form.courtPaymentModel}
418	                  onValueChange={(v) =>
419	                    setForm((f) => ({ ...f, courtPaymentModel: v as CourtPaymentModel }))
420	                  }
421	                  className="space-y-2 pt-1"
422	                >
423	                  <label className="flex items-start gap-3 rounded-lg border p-3 cursor-pointer hover:bg-muted/40 transition-colors">
424	                    <RadioGroupItem value="student_pays_court" id="pay-student" className="mt-0.5" />
425	                    <div className="flex-1 min-w-0">
426	                      <div className="text-sm font-medium">Mokinys moka už aikštelę</div>
427	                      <div className="text-xs text-muted-foreground">
428	                        Mokinys rezervuoja ir apmoka aikštelę atskirai. Jūs gaunate tik pamokos mokestį.
429	                      </div>
430	                    </div>
431	                  </label>
432	                  <label className="flex items-start gap-3 rounded-lg border p-3 cursor-pointer hover:bg-muted/40 transition-colors">
433	                    <RadioGroupItem value="coach_pays_court" id="pay-coach" className="mt-0.5" />
434	                    <div className="flex-1 min-w-0">
435	                      <div className="text-sm font-medium">Aš pats moku už aikštelę</div>
436	                      <div className="text-xs text-muted-foreground">
437	                        Jūs surenkate visą sumą ir pats atsiskaitote su aikštele iš savo dalies.
438	                      </div>
439	                    </div>
440	                  </label>
441	                </RadioGroup>
442	              </fieldset>
443	
444	              <fieldset className="space-y-2 rounded-2xl border bg-card p-4">
445	                <legend className="text-sm font-medium px-1">Atšaukimo taisyklės</legend>
446	                <p className="text-xs text-muted-foreground -mt-0.5">
447	                  Kiek grąžinama mokiniui, jei jis atšaukia pamoką. Aikštelės politika taikoma atskirai jos savininko.
448	                </p>
449	                <RadioGroup
450	                  value={form.cancellationPolicy}
451	                  onValueChange={(v) =>
452	                    setForm((f) => ({ ...f, cancellationPolicy: v as CoachCancellationPolicy }))
453	                  }
454	                  className="space-y-2 pt-1"
455	                >
456	                  <label className="flex items-start gap-3 rounded-lg border p-3 cursor-pointer hover:bg-muted/40 transition-colors">
457	                    <RadioGroupItem value="flexible" id="cancel-flexible" className="mt-0.5" />
458	                    <div className="flex-1 min-w-0">
459	                      <div className="text-sm font-medium">Lankstu</div>
460	                      <div className="text-xs text-muted-foreground">
461	                        100% grąžinama, jei atšaukiama ne vėliau kaip 24 val. iki pamokos.
462	                      </div>
463	                    </div>
464	                  </label>
465	                  <label className="flex items-start gap-3 rounded-lg border p-3 cursor-pointer hover:bg-muted/40 transition-colors">
466	                    <RadioGroupItem value="standard" id="cancel-standard" className="mt-0.5" />
467	                    <div className="flex-1 min-w-0">
468	                      <div className="text-sm font-medium">Standartinis</div>
469	                      <div className="text-xs text-muted-foreground">
470	                        80% grąžinama anksčiau nei 48 val., 50% — anksčiau nei 24 val., 0% — vėliau.
471	                      </div>
472	                    </div>
473	                  </label>
474	                  <label className="flex items-start gap-3 rounded-lg border p-3 cursor-pointer hover:bg-muted/40 transition-colors">
475	                    <RadioGroupItem value="strict" id="cancel-strict" className="mt-0.5" />
476	                    <div className="flex-1 min-w-0">
477	                      <div className="text-sm font-medium">Griežtas</div>
478	                      <div className="text-xs text-muted-foreground">
479	                        Apmokėjimas negrąžinamas, jei pamoka atšaukiama bet kokiu laiku.
480	                      </div>
481	                    </div>
482	                  </label>
483	                </RadioGroup>
484	              </fieldset>
485	
486	              <div className="flex justify-end pt-2">
487	                <Button type="submit" disabled={save.isPending || isViewingAs} title={isViewingAs ? "Žiūrite kaip kitas treneris — keisti negalima" : undefined}>
488	                  {save.isPending ? "Saugoma..." : "Išsaugoti"}
489	                </Button>
490	              </div>
491	            </form>
492	
493	            <CoachAffiliations />
494	          </>
495	        )}
496	      </div>
497	    </CoachLayout>
498	  );
499	}
