import { Router, type IRouter } from "express";
import { eq, and, desc, inArray, or, isNull, sql } from "drizzle-orm";
import { db, coachesTable, coachSportsTable, courtCoachesTable, courtCoachInvitationsTable, courtsTable, facilitiesTable, userProfilesTable } from "@workspace/db";
import { requireAuth, getCurrentUserId, isOwner, getUserRole, requireCoach, requireOwner, resolveCoachUserId } from "../lib/auth";
import { sendNotification } from "../lib/notify";
import { sendCoachInviteEmail } from "../lib/email";
import { getCoachAvailability, vilniusToUtc } from "../lib/coach-availability";
import { z } from "zod";
import { EmailString, OptionalEmailString, OptionalPhoneString } from "@workspace/api-zod";

const AUDIENCE_VALUES = ["kids", "beginners", "advanced", "pros"] as const;

const TRAVEL_POLICIES = ["any_court", "affiliated_only"] as const;
const COURT_PAYMENT_MODELS = ["student_pays_court", "coach_pays_court"] as const;
const COACH_CANCELLATION_POLICIES = ["flexible", "standard", "strict"] as const;

const SportAudienceEntry = z.object({
  sport: z.string().trim().min(1),
  audiences: z.array(z.enum(AUDIENCE_VALUES)).default([]),
});

const CoachUpsertBody = z.object({
  name: z.string().trim().min(2, "Vardas privalomas"),
  email: EmailString,
  bio: z.string().optional().nullable(),
  photoUrl: z.string().optional().nullable(),
  videoUrl: z.string().optional().nullable(),
  // pricePerHour intentionally not accepted: it's derived from active
  // coach_services by syncCoachStartingPrice. Letting clients set it would
  // reintroduce the bait-and-switch problem (low headline rate, high actual
  // service prices). Stale clients that still send it are silently stripped
  // by zod's default object behavior.
  sports: z.array(z.string()).optional(),
  // Per-sport target audiences. When supplied, replaces coach_sports for the
  // caller (sports without an entry default to empty audiences).
  sportsAudiences: z.array(SportAudienceEntry).optional(),
  availabilityDescription: z.string().optional().nullable(),
  phone: OptionalPhoneString,
  isAcceptingStudents: z.boolean().optional(),
  experienceYears: z.coerce.number().int().nonnegative().optional().nullable(),
  // Free-text credentials list. MVP is unverified — coaches type whatever they
  // want. Trim + drop empties; cap each entry's length to keep the public UI
  // sane and cap the array size to avoid abuse.
  qualifications: z
    .array(z.string().trim().min(1).max(200))
    .max(20)
    .optional(),
  travelPolicy: z.enum(TRAVEL_POLICIES).optional(),
  courtPaymentModel: z.enum(COURT_PAYMENT_MODELS).optional(),
  cancellationPolicy: z.enum(COACH_CANCELLATION_POLICIES).optional(),
});

/**
 * Replace-all sync of (sport, audiences[]) for a coach. Called from every
 * coach-upsert path so the junction table never drifts from coachesTable.sports.
 * The `sports` array on coachesTable is kept as a denormalized cache; this
 * helper rebuilds it from sportsAudiences when supplied.
 */
async function syncCoachSports(
  coachId: number,
  entries: Array<{ sport: string; audiences: string[] }>,
): Promise<void> {
  await db.transaction(async (tx) => {
    await tx.delete(coachSportsTable).where(eq(coachSportsTable.coachId, coachId));
    if (entries.length > 0) {
      await tx.insert(coachSportsTable).values(
        entries.map((e) => ({ coachId, sport: e.sport, audiences: e.audiences })),
      );
    }
  });
}

/**
 * Load the (sport, audiences) rows for a batch of coaches and return them
 * grouped by coachId. Used by formatters and the marketplace endpoint.
 */
async function loadSportsAudiences(
  coachIds: number[],
): Promise<Map<number, Array<{ sport: string; audiences: string[] }>>> {
  const map = new Map<number, Array<{ sport: string; audiences: string[] }>>();
  if (coachIds.length === 0) return map;
  const rows = await db
    .select({
      coachId: coachSportsTable.coachId,
      sport: coachSportsTable.sport,
      audiences: coachSportsTable.audiences,
    })
    .from(coachSportsTable)
    .where(inArray(coachSportsTable.coachId, coachIds));
  for (const r of rows) {
    if (!map.has(r.coachId)) map.set(r.coachId, []);
    map.get(r.coachId)!.push({ sport: r.sport, audiences: r.audiences });
  }
  return map;
}

