76	function WeeklyHoursSection() {
77	  const qc = useQueryClient();
78	  const { toast } = useToast();
79	
80	  const { asCoachId } = useViewAsCoach();
81	  const isViewingAs = asCoachId != null;
82	  const { data: rows, isLoading } = useQuery<AvailabilityRow[]>({
83	    queryKey: ["coach-availability", asCoachId],
