88	  const [days, setDays] = useState<Record<number, DayForm>>(() => seedDays([]));
89	
90	  // When the server data arrives, snapshot it into local form state. If a
91	  // weekday has multiple availability rows we collapse them to the earliest
92	  // start + latest end — split schedules aren't supported in this UI yet,
93	  // but the API + schema do support them for future expansion.
94	  useEffect(() => {
95	    if (!rows) return;
96	    setDays(seedDays(rows));
