98	
99	  const save = useMutation({
100	    mutationFn: async () => {
101	      const entries: Array<{ dayOfWeek: number; startTime: string; endTime: string }> = [];
102	      for (const dow of WEEK_ORDER) {
103	        const d = days[dow];
104	        if (!d?.enabled) continue;
105	        if (!d.startTime || !d.endTime) continue;
106	        if (d.startTime >= d.endTime) {
107	          throw new Error(`${WEEKDAY_LABELS[dow]}: pabaigos laikas turi būti vėlesnis už pradžią.`);
108	        }
109	        entries.push({ dayOfWeek: dow, startTime: d.startTime, endTime: d.endTime });
110	      }
