161	function seedDays(rows: AvailabilityRow[]): Record<number, DayForm> {
162	  const out: Record<number, DayForm> = {};
163	  for (const dow of WEEK_ORDER) out[dow] = { ...DEFAULT_DAY };
164	  // Collapse multiple ranges per day to a single envelope. Earliest start,
165	  // latest end. Good enough for the V1 "one shift per day" UI.
166	  for (const r of rows) {
167	    const cur = out[r.dayOfWeek] ?? { ...DEFAULT_DAY };
168	    const start = cur.enabled ? (r.startTime < cur.startTime ? r.startTime : cur.startTime) : r.startTime;
169	    const end = cur.enabled ? (r.endTime > cur.endTime ? r.endTime : cur.endTime) : r.endTime;
170	    out[r.dayOfWeek] = { enabled: true, startTime: start, endTime: end };
171	  }
172	  return out;
173	}
