296	          <div className="space-y-1.5 sm:col-span-2">
297	            <Label htmlFor="block-date">Data</Label>
298	            <Input
299	              id="block-date"
300	              type="date"
301	              value={form.date}
302	              onChange={(e) => setForm((f) => ({ ...f, date: e.target.value }))}
303	            />
304	          </div>
