316	            <Input
317	              id="block-end"
318	              type="time"
319	              value={form.endTime}
320	              onChange={(e) => setForm((f) => ({ ...f, endTime: e.target.value }))}
321	            />
322	          </div>
323	        </div>
324	        <div className="space-y-1.5">
325	          <Label htmlFor="block-reason">Priežastis (neprivaloma)</Label>
326	          <Textarea
327	            id="block-reason"
328	            rows={2}
329	            value={form.reason}
330	            onChange={(e) => setForm((f) => ({ ...f, reason: e.target.value }))}
331	            placeholder="Atostogos, varžybos..."
332	          />
333	        </div>
334	        <div className="flex justify-end">
335	          <Button
336	            onClick={() => create.mutate()}
337	            disabled={create.isPending || !form.date || isViewingAs}
338	            size="sm"
339	            title={isViewingAs ? "Žiūrite kaip kitas treneris — keisti negalima" : undefined}
340	          >
341	            <Plus className="h-4 w-4 mr-1" />
342	            Pridėti bloką
343	          </Button>
344	        </div>
345	      </div>
346	
347	      <div className="rounded-2xl border bg-card">
348	        {isLoading ? (
349	          <div className="p-4 space-y-2">
350	            <Skeleton className="h-12" />
351	            <Skeleton className="h-12" />
352	          </div>
353	        ) : sortedBlocks.length === 0 ? (
354	          <div className="p-6 text-center text-sm text-muted-foreground flex flex-col items-center gap-2">
355	            <CalendarOff className="h-8 w-8 opacity-30" />
356	            Šiuo metu suplanuotų blokų nėra.
