361	              <BlockedSlotRow
362	                key={b.id}
363	                block={b}
364	                onDelete={() => remove.mutate(b.id)}
365	                disabled={remove.isPending || isViewingAs}
366	              />
367	            ))}
368	          </ul>
369	        )}
370	      </div>
371	    </section>
372	  );
373	}
374	
375	function BlockedSlotRow({
376	  block,
377	  onDelete,
