import { useState, useMemo, useEffect } from "react";
import { Link } from "wouter";
import { useInfiniteQuery } from "@tanstack/react-query";
import { CoachLayout } from "@/components/coach-layout";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { EmptyState } from "@/components/empty-state";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import {
  CalendarDays, Clock, MapPin, Mail, Phone, Receipt, MessageCircle,
  ArrowUpDown, ChevronDown, Search, X, AlertCircle, Loader2,
} from "lucide-react";
import { customFetch } from "@workspace/api-client-react";
import { useViewAsCoach, withCoachViewAs } from "@/lib/view-as-coach";
import { centsToEuroString } from "@/lib/money";

const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");
const API = `${BASE}/api`;

type Scope = "all" | "upcoming" | "past";
type StatusFilter = "all" | "confirmed" | "awaiting_players" | "pending" | "cancelled";
type SortField = "date" | "price";
type SortOrder = "asc" | "desc";

interface BookingRow {
  id: number;
  date: string;
  startTime: string;
  endTime: string;
  durationMin: number;
  status: string;
  courtId: number | null;
  courtName: string | null;
  facilityName: string | null;
  serviceId: number | null;
  serviceName: string | null;
  customerName: string;
  customerEmail: string;
  customerPhone: string | null;
  bookerUserId: string | null;
  isManual: boolean;
  totalPriceCents: number;
  coachAmountCents: number | null;
  coachTransferId: string | null;
  refundCents: number;
  notes: string | null;
  createdAt: string;
}

interface BookingsResponse {
  items: BookingRow[];
  total: number;
  hasMore: boolean;
  limit: number;
  offset: number;
