import { db, coachesTable, bookingsTable, courtsTable, coachServicesTable } from "@workspace/db";
import { eq, like, sql, isNotNull } from "drizzle-orm";

async function main() {
  const coachCount = await db.select({ count: sql<number>`COUNT(*)::int` }).from(coachesTable);
  const demoCoaches = await db.select({
    id: coachesTable.id,
    userId: coachesTable.userId,
    name: coachesTable.name,
    status: coachesTable.status,
  }).from(coachesTable).where(like(coachesTable.userId, "demo-seed-%")).limit(20);

  console.log("Coach total:", coachCount[0]?.count);
  console.log("Demo coaches:", demoCoaches);

  const withCoach = await db.select({
    count: sql<number>`COUNT(*)::int`,
  }).from(bookingsTable).where(isNotNull(bookingsTable.coachId));
  console.log("Bookings WITH coach attached:", withCoach[0]?.count);

  const recentBookings = await db.select({
    id: bookingsTable.id,
    coachId: bookingsTable.coachId,
    customerName: bookingsTable.customerName,
    date: bookingsTable.date,
    startTime: bookingsTable.startTime,
    status: bookingsTable.status,
    totalPrice: bookingsTable.totalPrice,
  }).from(bookingsTable).where(isNotNull(bookingsTable.coachId)).limit(10);
  console.log("Sample coach bookings:", recentBookings);

  const services = await db.select({
    id: coachServicesTable.id,
    coachId: coachServicesTable.coachId,
    name: coachServicesTable.name,
    courtId: coachServicesTable.courtId,
    durationMin: coachServicesTable.durationMin,
    priceCents: coachServicesTable.priceCents,
    isActive: coachServicesTable.isActive,
  }).from(coachServicesTable).limit(5);
  console.log("Coach services:", services);

  process.exit(0);
}
main().catch((e) => { console.error(e); process.exit(1); });
EOF
