  const p = new URLSearchParams(window.location.search);
  const scope = SCOPE_VALUES.includes(p.get("scope") as Scope)
    ? (p.get("scope") as Scope) : "upcoming";
  const status = STATUS_VALUES.includes(p.get("status") as StatusFilter)
    ? (p.get("status") as StatusFilter) : "all";
  const sortField = SORT_FIELD_VALUES.includes(p.get("sort") as SortField)
    ? (p.get("sort") as SortField) : "date";
  const orderRaw = p.get("order");
