useEffect(() => {
  const id = setTimeout(() => setDebouncedSearch(search.trim()), SEARCH_DEBOUNCE_MS);
  return () => clearTimeout(id);
}, [search]);

// Sync filter state back to the URL with replaceState so reloads and shares
// preserve the view, but back/forward isn't littered with every keystroke.
// We drop default values to keep the URL clean ("scope=upcoming" + no
// search + no status filter is just `/coach/bookings`).
useEffect(() => {
  const p = new URLSearchParams();
  if (scope !== "upcoming") p.set("scope", scope);
  if (status !== "all") p.set("status", status);
  if (debouncedSearch) p.set("search", debouncedSearch);
  if (sortField !== "date") p.set("sort", sortField);
  if (sortOrder) p.set("order", sortOrder);
  const qs = p.toString();
  const target = qs ? `/coach/bookings?${qs}` : "/coach/bookings";
  const current = window.location.pathname + window.location.search;
  if (current.endsWith(target.replace(/^\/coach\/bookings/, "")) ? current === target : true) {
    // The check above is a no-op safety: always call navigate(replace) so
    // we end up exactly at `target` (idempotent thanks to replaceState).
    navigate(target, { replace: true });
  }
}, [scope, status, debouncedSearch, sortField, sortOrder, navigate]);

