await page.waitForTimeout(800);  // debounce + URL write
console.log("4. URL after search:", page.url());

// Click "Visi"
await page.locator("button:has-text('Visi')").first().click();
await page.waitForTimeout(500);
console.log("5. URL after Visi click:", page.url());

// Reload with that URL to confirm params survive
const finalUrl = page.url();
console.log("6. Reloading:", finalUrl);
await page.goto(finalUrl, { waitUntil: "networkidle" });
await page.waitForTimeout(2000);

// Verify state in DOM
const scopeActive = await page.locator("button.bg-card").allTextContents();
const statusValue = await page.locator("button[role=combobox]").first().textContent();
const searchValue = await page.locator("input[placeholder^='Ieškoti']").inputValue();
console.log("7. After reload:");
console.log("   active scope buttons:", scopeActive.filter(t => ["Visi", "Būsimi", "Praėję"].includes(t)));
console.log("   status filter:", statusValue);
console.log("   search input value:", searchValue);

await browser.close();

