import { chromium } from "playwright";

const BYPASS_KEY = "test_bypass_key_local_only";
const COACH_USER_ID = "demo-seed-coach-egle-tennis-kaunas";

const browser = await chromium.launch({
  executablePath: process.env.CHROMIUM_PATH,
  headless: true,
  args: ["--no-sandbox", "--disable-setuid-sandbox", "--disable-dev-shm-usage", "--disable-gpu", "--lang=lt-LT"],
});
const context = await browser.newContext({
  viewport: { width: 1280, height: 1100 },
  locale: "lt-LT",
});
await context.addInitScript(() => { window.__E2E_FAKE_SIGNIN = true; });
await context.route("**/*", (route, request) => {
  if (request.url().includes("/api/")) {
    route.continue({
      headers: {
        ...request.headers(),
        "x-replit-agent-auth": BYPASS_KEY,
        "x-replit-agent-userid": COACH_USER_ID,
        "x-replit-agent-role": "coach",
      },
    });
  } else route.continue();
});
const page = await context.newPage();

// Deep link directly to a filtered view — this is what the URL-params task
// was supposed to enable.
await page.goto("http://localhost:5173/coach/bookings?scope=past&status=cancelled", { waitUntil: "networkidle" });
await page.waitForTimeout(2500);
console.log("URL on load:", page.url());

// Check which scope button is active. The active one has the "bg-card" class
// in the segmented control.
const activeScope = await page.evaluate(() => {
  const buttons = Array.from(document.querySelectorAll("button"));
  const candidates = buttons.filter((b) => ["Visi", "Būsimi", "Praėję"].includes((b.textContent ?? "").trim()));
  return candidates.find((b) => b.className.includes("bg-card"))?.textContent?.trim() ?? null;
});
console.log("Active scope tab:", activeScope);

// Check the status filter's displayed value.
const statusBtn = await page.locator("button[role=combobox]").first().textContent();
console.log("Status filter text:", statusBtn);

// Count cancelled-status badges that should appear on every row.
const cancelledBadgeCount = await page.locator("text=Atšaukta").count();
console.log("Atšaukta badges on page:", cancelledBadgeCount);

await page.screenshot({ path: "/tmp/screenshots/url-sync-verify.png", fullPage: true });

await browser.close();
console.log("Done");

