import { chromium } from "playwright";

const browser = await chromium.launch({
  executablePath: process.env.CHROMIUM_PATH,
  headless: true,
  args: ["--no-sandbox", "--disable-setuid-sandbox", "--disable-dev-shm-usage", "--disable-gpu", "--lang=lt-LT"],
});
const context = await browser.newContext({
  viewport: { width: 1280, height: 1100 },
  locale: "lt-LT",
});
const page = await context.newPage();

async function shotAndProbe(label, url) {
  await page.goto(url, { waitUntil: "networkidle" });
  await page.waitForTimeout(2000);
  const safe = label.toLowerCase().replace(/[^a-z0-9]+/g, "-");
  await page.screenshot({ path: `/tmp/screenshots/${safe}.png`, fullPage: true });
  console.log(`Saved ${safe}.png — URL: ${page.url()}`);
}

// ── COACHES PAGE ──
console.log("=== Coaches page ===");
await shotAndProbe("coaches-initial", "http://localhost:5173/coaches");

// Click "Tenisas" sport pill in the sidebar
await page.locator("aside button:has-text('Tenisas'), button:has-text('Tenisas')").first().click();
await page.waitForTimeout(800);
await shotAndProbe("coaches-after-tennis-click", "http://localhost:5173/coaches");

// Click Tenisas again — should reset to all
await page.locator("aside button:has-text('Tenisas'), button:has-text('Tenisas')").first().click();
await page.waitForTimeout(800);
await shotAndProbe("coaches-after-second-click", "http://localhost:5173/coaches");

// ── COURTS PAGE ──
console.log("\n=== Courts page ===");
