288	  // Time + duration — required by the availability matrix. When all three of
289	  // (date, time, duration) are present we pipe them to the /coaches endpoint
290	  // and the server filters by getCoachAvailability continuous coverage.
291	  const [searchTime, setSearchTime] = useState("");          // "HH:MM"
292	  const [searchDurationMin, setSearchDurationMin] = useState(60); // 30 | 60 | 90 | 120
293	  const [timeDropdownOpen, setTimeDropdownOpen] = useState(false);
