311	  const TIME_PALETTES = [
312	    { color: "#38bdf8" }, // dawn
313	    { color: "#84cc16" }, // morning
314	    { color: "#f59e0b" }, // afternoon
315	    { color: "#f97316" }, // evening
316	    { color: "#8b5cf6" }, // night
317	  ];
318	  const timePalette =
319	    currentHour >= 5 && currentHour < 10 ? TIME_PALETTES[0] :
320	    currentHour >= 10 && currentHour < 14 ? TIME_PALETTES[1] :
321	    currentHour >= 14 && currentHour < 17 ? TIME_PALETTES[2] :
322	    currentHour >= 17 && currentHour < 21 ? TIME_PALETTES[3] :
323	    TIME_PALETTES[4];
324	  const timeAccent = timePalette.color;
325	  const accentColor = searchSport ? (sportColor[searchSport] ?? timeAccent) : timeAccent;
326	  function contrastText(hex: string) {
327	    const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
328	    return (0.299*r + 0.587*g + 0.114*b) / 255 > 0.55 ? "#000" : "#fff";
