372	
373	  // Sidebar filters
374	  const [search, setSearch] = useState("");
375	  const [activeSports, setActiveSports] = useState<Set<string>>(
376	    initialSport ? new Set([initialSport]) : new Set(ALL_SPORTS)
377	  );
378	  const [maxPrice, setMaxPrice] = useState(200);
379	  const [sortBy, setSortBy] = useState<"default" | "price_asc" | "price_desc" | "rating_desc">("default");
