396	  }, [search, activeSports, maxPrice, sortBy, searchCity, searchDate, searchTime, searchDurationMin, activeAudiences, travelOnly, flexibleOnly]);
397	
398	  const allSportsActive = activeSports.size === ALL_SPORTS.length;
399	  // Single-select sport filter: clicking a sport narrows to JUST that sport
400	  // in one click. Clicking the currently-only-selected sport widens back to
401	  // "all sports active" (the unfiltered state). No multi-select — the user
402	  // explicitly asked for "filtering by sport should be one click only".
403	  const toggleSport = (sport: string) => {
404	    setActiveSports(prev => {
405	      if (prev.size === 1 && prev.has(sport)) {
406	        return new Set(ALL_SPORTS);
407	      }
408	      return new Set([sport]);
409	    });
410	  };
411	  const resetSports = () => setActiveSports(new Set(ALL_SPORTS));
412	
413	  const filteredCoaches = (coaches ?? []).filter(c => {
414	    const matchesSearch = !search.trim() ||
415	      c.name.toLowerCase().includes(search.toLowerCase()) ||
416	      (c.bio ?? "").toLowerCase().includes(search.toLowerCase());
417	    const matchesSport = activeSports.size === ALL_SPORTS.length || c.sports.some(s => activeSports.has(s));
