420	    const matchesCity = !searchCity || (c.cities ?? []).some(
421	      city => city.toLowerCase() === searchCity.toLowerCase()
422	    );
423	    return matchesSearch && matchesSport && matchesPrice && matchesCity;
424	  });
425	
