427	    if (sortBy === "rating_desc") return ((b as any).rating ?? 0) - ((a as any).rating ?? 0);
428	    if (sortBy === "price_asc") return (a.pricePerHour ?? 999) - (b.pricePerHour ?? 999);
429	    if (sortBy === "price_desc") return (b.pricePerHour ?? 0) - (a.pricePerHour ?? 0);
430	    return 0;
