}

export function CancellationTimeline({ hoursUntilStart }: Props) {
  const tiers: Tier[] = [
    {
      hours: "> 48 val.",
      percent: 80,
      label: "80% grąžinama",
      color: "text-green-600 dark:text-green-400",
      bgColor: "bg-green-500/10",
      borderColor: "border-green-400/30",
