<div className="flex items-stretch gap-2">
  <div className="flex-1 flex gap-2 overflow-x-auto pb-1 -mx-0.5 px-0.5 scrollbar-thin">
    {Array.from({ length: 7 }).map((_, i) => {
      const d = addDays(new Date(new Date().setHours(0, 0, 0, 0)), i);
      const isSelected = isSameDay(d, date);
      const topLabel =
        i === 0
          ? "Šiandien"
          : i === 1
            ? "Rytoj"
            : format(d, "EEE", { locale: ltLocale });
      const subLabel = format(d, "MMM d", { locale: ltLocale });
      return (
        <button
          key={i}
          type="button"
          onClick={() => {
            vibrateTap();
            setDate(d);
            setSelectedStart(null);
            setSelectedEnd(null);
            setSelectedEquipment(new Map());
          }}
          className={`shrink-0 min-w-[78px] rounded-xl border px-2.5 py-2 text-center transition-colors ${
            isSelected
              ? "border-primary bg-primary/10 text-primary"
