          aria-pressed={isSelected}
        >
          <div className={`text-[10px] font-semibold uppercase tracking-wide ${isSelected ? "text-primary" : "text-muted-foreground"}`}>
            {topLabel}
          </div>
          <div className="text-sm font-semibold leading-tight mt-0.5">
            {subLabel}
          </div>
        </button>
